import * as THREE from 'three/webgpu';
import { color, float } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'orrery-mechanism';

  const timelines = [];
  const disposables = [];
  const clockState = { t: 0 };

  // Backdrop plane
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicNodeMaterial();
  backdropMat.colorNode = color('#101017');
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // Fog hint
  group.userData.fog = new THREE.Fog(0x0b0b10, 5, 11);

  // Contact shadow ellipse
  const shadowGeo = new THREE.CircleGeometry(1, 48);
  shadowGeo.scale(1.3, 0.6, 1);
  const shadowMat = new THREE.MeshBasicNodeMaterial({ transparent: true, opacity: 0.5 });
  shadowMat.colorNode = color('#0b0b10');
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // Gear material (machined steel)
  const gearMat = new THREE.MeshPhysicalNodeMaterial();
  gearMat.roughness = 0.5;
  gearMat.metalness = 0.55;
  gearMat.clearcoat = 0.2;
  gearMat.clearcoatRoughness = 0.3;
  gearMat.anisotropy = 0.7;
  gearMat.colorNode = color('#14141a');
  disposables.push(gearMat);

  const primaryGroup = new THREE.Group();
  primaryGroup.name = 'primary-gear';
  const secondaryGroup = new THREE.Group();
  secondaryGroup.name = 'secondary-gear';
  secondaryGroup.position.set(1.15, 0.35, -0.1);

  group.add(primaryGroup, secondaryGroup);

  // Load GLB meshes
  const gearGltf = ctx.glbLoader.load(config.assets?.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb');
  const applyGear = (gltf, target, diameter) => {
    if (!gltf || !gltf.scene) return;
    const mesh = gltf.scene.clone(true);
    const box = new THREE.Box3().setFromObject(mesh);
    const size = new THREE.Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y, size.z) || 1;
    const scaleFactor = diameter / maxDim;
    mesh.scale.setScalar(scaleFactor);
    const center = new THREE.Vector3();
    box.getCenter(center);
    mesh.position.sub(center.multiplyScalar(scaleFactor));
    mesh.traverse((child) => {
      if (child.isMesh) {
        child.material = gearMat;
        child.castShadow = true;
        child.receiveShadow = true;
      }
    });
    target.add(mesh);
  };

  if (gearGltf && gearGltf.scene) {
    applyGear(gearGltf, primaryGroup, 1.6);
    applyGear(gearGltf, secondaryGroup, 0.9);
  } else if (gearGltf && typeof gearGltf.then === 'function') {
    // in case textureLoader/glbLoader returns a cached promise-like, handle gracefully
    gearGltf.then((g) => {
      applyGear(g, primaryGroup, 1.6);
      applyGear(g, secondaryGroup, 0.9);
    });
  }

  // Arbor shafts
  const shaftGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new THREE.MeshPhysicalNodeMaterial();
  shaftMat.colorNode = color('#16161d');
  shaftMat.roughness = 0.4;
  shaftMat.metalness = 0.3;
  const primaryShaft = new THREE.Mesh(shaftGeo, shaftMat);
  primaryShaft.rotation.x = Math.PI / 2;
  primaryGroup.add(primaryShaft);
  const secondaryShaft = new THREE.Mesh(shaftGeo, shaftMat);
  secondaryShaft.rotation.x = Math.PI / 2;
  secondaryGroup.add(secondaryShaft);
  disposables.push(shaftGeo, shaftMat);

  // Jewel pivot
  const jewelGeo = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMat = new THREE.MeshPhysicalNodeMaterial();
  jewelMat.colorNode = color('#ff2a38');
  jewelMat.transmission = 0.6;
  jewelMat.ior = 1.76;
  jewelMat.emissiveNode = color('#ff2a38').mul(float(1.8));
  jewelMat.roughness = 0.1;
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  primaryGroup.add(jewel);
  disposables.push(jewelGeo, jewelMat);

  // Text content
  const headline = createTextMesh(ctx.fontAtlas, {
    text: 'The going train',
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(0, -1.7, 0);
  group.add(headline);

  const caption = createTextMesh(ctx.fontAtlas, {
    text: '34 COMPONENTS / HAND-FINISHED',
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
  });
  caption.position.set(0, -2.1, 0);
  group.add(caption);

  // Scene placement
  const pos = config.scenePlacement?.position || [0, 0, 0];
  const rot = config.scenePlacement?.rotation || [0, 0, 0];
  const scl = config.scenePlacement?.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  // Apply cinematic primitives
  (config.cinematicPrimitives || []).forEach((primitive) => {
    const fn = ctx.primitives[primitive.name];
    if (fn) fn(group, primitive.params);
  });

  // Meshing rotation animation (weighted-settle style, phase-locked ratio 16:9)
  const primarySpeed = 0.08;
  const secondarySpeed = -0.142;
  const rotationTicker = () => {
    clockState.t += 1 / 60;
    primaryGroup.rotation.z = primarySpeed * clockState.t * Math.PI * 2 * 0.15;
    secondaryGroup.rotation.z = secondarySpeed * clockState.t * Math.PI * 2 * 0.15;
  };
  gsap.ticker.add(rotationTicker);

  // Weighted-settle intro
  const settleTl = gsap.timeline();
  settleTl.fromTo(group.scale, { x: scl[0] * 1.04, y: scl[1] * 1.04, z: scl[2] * 1.04 },
    { x: scl[0], y: scl[1], z: scl[2], duration: 0.9, ease: 'power4.out' });
  timelines.push(settleTl);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    gsap.ticker.remove(rotationTicker);
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => d.dispose && d.dispose());
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      }
    });
  };

  return group;
}
